S = "Hakeem Force Academy"
QS = [
(S, "What was Hilf-ul-Fudul (Half-e-Fadool)?", ["A pre-Islamic pact in Makkah to protect the oppressed and uphold justice", "A treaty signed between the Muslims and the Quraish in 6 AH", "A pact made by the Ansar of Madinah at Aqabah", "A trade agreement between Makkah and Syria"], 0, "Hilf-ul-Fudul was a pledge made by several Makkan clans to help victims of injustice and to see that wrongs were set right. The Prophet (PBUH) took part in it as a young man.", "The Prophet (PBUH) said that even after Islam he would respond to a similar call.", 1),
(S, "What does the term Ijtehad mean in Islamic law?", ["Independent reasoning to derive rulings from the Quran and Sunnah", "Migration for the sake of faith", "Consensus of all companions", "Voluntary night prayer"], 0, "Ijtehad means exerting one's utmost intellectual effort to find a legal ruling on a new matter from the Quran and Sunnah. A scholar who does this is called a Mujtahid.", "Allama Iqbal strongly advocated Ijtehad as the principle of movement in Islam.", 1),
(S, "What does the Arabic word Mantiq mean?", ["Grammar", "Logic", "Poetry", "Rhetoric"], 1, "Mantiq is the Arabic word for logic, the science of correct reasoning. It is taught in Dars-e-Nizami madrassas.", "Muslim philosophers such as Al-Farabi and Ibn Sina wrote extensively on Mantiq.", 1),
(S, "What does NFC stand for in Pakistan's finance system?", ["National Finance Commission", "National Fiscal Council", "Federal Finance Committee", "National Funds Corporation"], 0, "NFC stands for National Finance Commission. It decides how federal tax revenue is shared between the federation and the provinces.", "The 7th NFC Award of 2010 gave the provinces 57.5 percent of the divisible pool.", 1),
(S, "What is 28 May, the day Pakistan conducted its nuclear tests in 1998, known as?", ["Youm-e-Takbeer", "Youm-e-Tashakur", "Youm-e-Pakistan", "Youm-e-Istehsal"], 0, "On 28 May 1998 Pakistan carried out nuclear tests at Chagai, and the day is observed as Youm-e-Takbeer. Takbeer means proclaiming the greatness of God.", "Pakistan became the seventh nuclear power and the first Muslim nuclear state.", 2),
(S, "What does the abbreviation PSL stand for in Pakistani cricket?", ["Pakistan Super League", "Pakistan Sports League", "Pakistan Senior League", "Premier Super League"], 0, "PSL stands for Pakistan Super League, the franchise Twenty20 cricket league of Pakistan. It began in 2016.", "The PSL is run by the Pakistan Cricket Board.", 1),
(S, "What does the word Pakistan mean?", ["Land of the pure", "Land of truth", "Land of five rivers", "Land of the brave"], 0, "Pakistan is a Persian and Urdu word made of pak (pure) and stan (land), so it means land of the pure. It is not related to truth.", "The name was proposed by Choudhry Rahmat Ali in 1933 in the pamphlet Now or Never.", 2),
(S, "What does the word seething mean?", ["Boiling with anger or agitation", "Sleeping deeply", "Laughing loudly", "Moving very slowly"], 0, "To seethe is to boil or churn, and it is used for a person who is extremely angry but does not show it. So seething means very angry.", "Its literal meaning is bubbling as a liquid does when boiling.", 1),
(S, "What does Tayammum mean?", ["Dry ablution with clean earth when water is unavailable", "Ablution with water", "Ritual bath after major impurity", "Call to prayer"], 0, "Tayammum is a substitute for wudu or ghusl performed with clean earth or dust when water is not available or cannot be used. It is taught in the Quran in Surah Al-Maidah.", "Tayammum is made by striking the hands on clean earth and wiping the face and hands.", 1),
(S, "What does the Silk Route connect?", ["China with the Mediterranean and Europe", "India with Africa", "Russia with Japan", "America with Europe"], 0, "The Silk Route was an ancient network of trade roads linking China through Central Asia to the Mediterranean world. Silk was a major good carried along it.", "The Karakoram Highway in Pakistan follows part of the old Silk Route.", 1),
(S, "What does the word Akhuwat mean?", ["Brotherhood", "Charity", "Prayer", "Loan"], 0, "Akhuwat is an Arabic and Urdu word meaning brotherhood. It is the name of a Pakistani organisation that gives interest-free loans.", "The Akhuwat concept is based on the brotherhood between the Muhajirin and the Ansar of Madinah.", 1),
(S, "What does the word Quran literally mean?", ["That which is recited or read", "The book of rules", "The final guide", "The light of God"], 0, "Quran comes from the Arabic root q-r-a, meaning to read or recite, so it literally means the recitation. It is the name of the holy book of Muslims.", "The first revelation to the Prophet (PBUH) began with the command Iqra, meaning read.", 1),
(S, "What does wuzu (wudu) mean?", ["Ritual washing before prayer", "Fasting", "Pilgrimage", "Charity"], 0, "Wuzu is the ritual ablution in which the face, arms, head and feet are washed or wiped before prayer. It is a condition for offering Salah.", "Wuzu comes from an Arabic word connected with cleanliness and brightness.", 2),
(S, "What important event took place in 622 AD?", ["The Hijrah (migration) of the Prophet (PBUH) from Makkah to Madinah", "The Battle of Badr", "The Conquest of Makkah", "The Treaty of Hudaibiyah"], 0, "The Prophet (PBUH) migrated from Makkah to Madinah in 622 AD. This year marks the start of the Islamic Hijri calendar.", "The Hijri calendar was introduced in the time of Hazrat Umar (RA).", 1),
(S, "What is the value of 0! (zero factorial)?", ["1", "0", "Undefined", "Infinity"], 0, "By definition 0! = 1, because there is exactly one way to arrange no objects. This also keeps the formula n! = n x (n-1)! true for n = 1.", "The number of ways to choose 0 items from n, nC0, equals 1 for this reason.", 1),
(S, "What is a period of 100 years also called?", ["Century", "Decade", "Millennium", "Score"], 0, "A century is a period of 100 years. A decade is 10 years and a millennium is 1000 years.", "A score means 20 years or 20 items.", 1),
(S, "What is 22 March observed as worldwide?", ["World Water Day", "World Health Day", "World Environment Day", "World Population Day"], 0, "The United Nations observes 22 March each year as World Water Day. It raises awareness of fresh water and its sustainable use.", "World Environment Day is on 5 June and World Health Day on 7 April.", 1),
(S, "What does the United Nations observe on 24 January?", ["International Day of Education", "International Day of Peace", "International Literacy Day", "World Teachers Day"], 0, "The UN General Assembly proclaimed 24 January as International Day of Education in December 2018. It was first observed in 2019.", "International Literacy Day is on 8 September and World Teachers Day on 5 October.", 1),
(S, "What is the value of (3 - 2i) - (3 + 2i)?", ["-4i", "4i", "0", "6 - 4i"], 0, "Subtract the real parts: 3 - 3 = 0. Subtract the imaginary parts: -2i - 2i = -4i, so the answer is -4i.", "The product of a complex number and its conjugate is always a real number.", 1),
(S, "What is an angle of 90 degrees called?", ["Right angle", "Acute angle", "Obtuse angle", "Straight angle"], 0, "An angle of exactly 90 degrees is called a right angle. Acute angles are smaller and obtuse angles are larger.", "A straight angle measures 180 degrees.", 1),
(S, "What was the relation of A. O. Hume with the Indian National Congress?", ["He was one of its founders in 1885", "He was its first Muslim president", "He was its fiercest opponent", "He was the Viceroy who banned it"], 0, "Allan Octavian Hume, a retired British civil servant, helped found the Indian National Congress in December 1885. He served as its first general secretary.", "The first president of the Congress was W. C. Bonnerjee.", 1),
(S, "Which word is a synonym of alter?", ["Change", "Preserve", "Keep", "Fix in place"], 0, "To alter means to make something different, which is the same as to change it. The other options mean the opposite.", "The noun form of alter is alteration.", 1),
(S, "Which word is a synonym of complicated?", ["Complex", "Simple", "Easy", "Plain"], 0, "Complicated means made of many parts and hard to understand, which is the meaning of complex. Simple, easy and plain are its opposites.", "The opposite of complicated is simple.", 1),
(S, "Which word is a synonym of conceal?", ["Hide", "Reveal", "Show", "Expose"], 0, "To conceal means to keep something out of sight, which is to hide it. Reveal, show and expose are antonyms.", "The noun form is concealment.", 1),
]
